import json
import os
import time

import pytest
from fastapi.testclient import TestClient

from forge import orca_link, spools

GCODE = """; HEADER_BLOCK_START
; generated by OrcaSlicer 2.5.2
; filament used [g] = 12.34, 0, 3.21
; filament used [mm] = 4100.2, 0, 1066.5
; HEADER_BLOCK_END
G1 X10 Y10
; CONFIG_BLOCK_START
; filament_settings_id = "Giantarm PLA @Snapmaker U1";"Generic PLA";"Generic PETG"
; filament_colour = #FF0000;#00FF00;#0000FF
; printer_settings_id = "Snapmaker U1 (0.4 nozzle)"
; CONFIG_BLOCK_END
"""


def test_parse_gcode_usage_per_slot():
    u = spools.parse_usage(GCODE)
    assert [(s["slot"], s["grams"], s["preset"]) for s in u["slots"]] == [
        (1, 12.34, "Giantarm PLA @Snapmaker U1"), (3, 3.21, "Generic PETG")]
    assert u["total_g"] == 15.55
    assert u["printer"] == "Snapmaker U1 (0.4 nozzle)"
    # no weight written (density not set): worked out from length, PLA-ish density
    u2 = spools.parse_usage("; filament used [mm] = 1000\n; filament_density = 0\n")
    assert u2["slots"][0]["grams"] == pytest.approx(2.98, abs=0.02)


def test_big_gcode_keeps_head_and_tail():
    raw = GCODE.split("G1")[0].encode() + b"G1 X1\n" * 400_000 + b"; filament_settings_id = \"A\"\n"
    u = spools.parse_usage(spools.read_gcode_bytes(raw))
    assert u["slots"][0]["preset"] == "A"


def _orca(root, current="Snapmaker U1 (0.4 nozzle)"):
    sysdir = root / "system" / "Snapmaker" / "machine"
    sysdir.mkdir(parents=True)
    (sysdir / "fdm_u1_common.json").write_text(json.dumps({
        "name": "fdm_u1_common", "printer_structure": "corexy", "machine_max_speed_x": ["500", "200"],
        "machine_max_speed_y": ["450"], "machine_max_acceleration_extruding": ["20000"],
        "printable_area": ["0x0", "270x0", "270x270", "0x270"], "printable_height": "270"}))
    (sysdir / "u1.json").write_text(json.dumps({
        "name": "Snapmaker U1 (0.4 nozzle)", "inherits": "fdm_u1_common",
        "nozzle_diameter": ["0.4", "0.4", "0.4", "0.4"], "printer_model": "Snapmaker U1"}))
    (sysdir / "unused.json").write_text(json.dumps({"name": "Some Other Printer", "nozzle_diameter": ["0.4"]}))
    userdir = root / "user" / "default" / "machine"
    userdir.mkdir(parents=True)
    (userdir / "cc.json").write_text(json.dumps({
        "name": "Elegoo Centauri Carbon - hers", "inherits": "Snapmaker U1 (0.4 nozzle)",
        "nozzle_diameter": ["0.4"], "printable_area": ["0x0", "256x0", "256x256", "0x256"], "printable_height": "256"}))
    (root / "user" / "default" / "filament").mkdir(parents=True, exist_ok=True)
    write_conf(root, current, ["Giantarm PLA @Snapmaker U1", "Generic PLA"], "#FF0000,#00FF00")


def write_conf(root, printer, filaments, colours):
    entry = {"machine": printer, "filament": filaments[0], "filament_colors": colours}
    for i, f in enumerate(filaments[1:], 1):
        entry[f"filament_{i:02d}"] = f
    conf = {"presets": {"machine": printer, "filaments": filaments, "filament_colors": colours},
            "orca_presets": [entry], "local_machines": {"x": {"access_code": "secret"}}}
    path = root / "OrcaSlicer.conf"
    path.write_text(json.dumps(conf) + "\n# MD5 checksum 0123\n")
    st = path.stat()
    os.utime(path, (st.st_atime, st.st_mtime + 2))  # make sure the change is seen


def test_orca_printers_inherit_and_map(tmp_path):
    _orca(tmp_path)
    found = {p["name"]: p for p in orca_link.printers(tmp_path)}
    assert "Some Other Printer" not in found  # never used in Orca, not yours
    u1 = found["Snapmaker U1 (0.4 nozzle)"]["fields"]
    assert u1 == {"orca_printer": "Snapmaker U1 (0.4 nozzle)", "toolheads": 4, "nozzle_diameter": 0.4,
                  "max_velocity": 450, "max_accel": 20000, "kinematics": "corexy",
                  "bed_x": 270, "bed_y": 270, "bed_z": 270, "orca_model": "Snapmaker U1"}
    cc = found["Elegoo Centauri Carbon - hers"]
    assert cc["user"] and cc["fields"]["toolheads"] == 1 and cc["fields"]["bed_x"] == 256
    sel = orca_link.selection(orca_link.read_conf(tmp_path))
    assert sel["filaments"] == ["Giantarm PLA @Snapmaker U1", "Generic PLA"]
    assert sel["colours"] == ["#FF0000", "#00FF00"]


@pytest.fixture
def client(tmp_path, monkeypatch):
    root = tmp_path / "orca"
    _orca(root)
    monkeypatch.setenv("ORCA_CONFIG_DIR", str(root))
    from forge import app as app_mod
    monkeypatch.setattr(app_mod, "DATA_DIR", tmp_path)
    monkeypatch.setattr(app_mod, "PHOTO_DIR", tmp_path / "photos")
    c = TestClient(app_mod.create_app(tmp_path / "t.db", manage_ai=False))
    c.root = root
    return c


def _profile(client, name="Giantarm PLA @Snapmaker U1"):
    f = client.post("/api/filaments", json={"name": "Giantarm PLA", "material": "PLA", "spec": {}}).json()
    p = client.post("/api/profiles", json={"filament_id": f["id"], "printer_id": 1}).json()
    client.put(f"/api/profiles/{p['id']}", json={"name": name, "settings": p["settings"]})
    return client.get(f"/api/profiles/{p['id']}").json()


def test_link_printer_and_follow_orca_slots(client):
    prof = _profile(client)
    listed = client.get("/api/orca/printers").json()["printers"]
    assert listed[0]["name"] == "Snapmaker U1 (0.4 nozzle)" and listed[0]["current"]
    pr = client.post("/api/printers/link-orca", json={"orca_printer": "Snapmaker U1 (0.4 nozzle)",
                                                     "printer_id": 1}).json()
    assert pr["data"]["orca_link"] and pr["data"]["max_velocity"] == 450 and pr["data"]["toolheads"] == 4
    loaded = pr["data"]["loaded"]
    assert loaded["1"]["profile_id"] == prof["id"] and loaded["1"]["source"] == "orca"
    assert loaded["2"]["profile_id"] is None and loaded["2"]["name"] == "Generic PLA"
    assert loaded["2"]["colour"] == "#00FF00"
    assert client.get(f"/api/profiles/{prof['id']}").json()["loaded_in"][0]["toolhead"] == 1

    # you choose T3 in the app: Orca hasn't changed, so the app keeps your choice
    client.put("/api/printers/1/toolheads/3", json={"profile_id": prof["id"]})
    client.get("/api/orca/live")
    assert client.get("/api/printers").json()[0]["data"]["loaded"]["3"]["profile_id"] == prof["id"]

    # you change slot 1 in Orca: the app follows
    write_conf(client.root, "Snapmaker U1 (0.4 nozzle)", ["Generic PETG", "Giantarm PLA @Snapmaker U1"], "#000000,#FF0000")
    live = client.get("/api/orca/live").json()
    assert live["slots"][0]["name"] == "Generic PETG" and 1 in live["changed"]
    loaded = client.get("/api/printers").json()[0]["data"]["loaded"]
    assert loaded["1"]["name"] == "Generic PETG" and loaded["2"]["profile_id"] == prof["id"]

    # a second printer for someone else, from their own Orca printer
    cc = client.post("/api/printers/link-orca", json={"orca_printer": "Elegoo Centauri Carbon - hers"}).json()
    assert cc["name"] == "Elegoo Centauri Carbon - hers" and cc["data"]["toolheads"] == 1
    # the conf never leaks: printer access codes aren't stored
    assert "secret" not in json.dumps(client.get("/api/printers").json())


def test_spools_numbered_weighed_and_used(client):
    prof = _profile(client)
    made = client.post("/api/spools", json={"profile_id": prof["id"], "net_g": 1000, "tare_g": 180, "count": 2}).json()
    assert [s["label"] for s in made] == ["Giantarm PLA #1", "Giantarm PLA #2"]
    third = client.post("/api/spools", json={"profile_id": prof["id"]}).json()[0]
    assert third["number"] == 3
    s1, s2 = made[0]["id"], made[1]["id"]

    # load spool #2 in T1, then Orca reports a print
    client.put("/api/printers/1/toolheads/1", json={"profile_id": prof["id"], "spool_id": s2})
    r = client.post("/api/usage/report", json={"job": "benchy", "usage": spools.parse_usage(GCODE)}).json()
    assert len(r["recorded"]) == 2
    sp2 = client.get("/api/spools").json()
    by = {s["id"]: s for s in sp2}
    assert by[s2]["remaining_g"] == pytest.approx(987.66) and by[s1]["remaining_g"] == 1000
    # the same export reported twice isn't counted twice
    assert client.post("/api/usage/report", json={"job": "benchy", "usage": spools.parse_usage(GCODE)}).json()["recorded"] == []

    # it failed at 50%: half goes back
    use = client.get("/api/usage").json()
    first = next(u for u in use if u["slot"] == 1)
    assert first["spool"] == "Giantarm PLA #2"
    client.put(f"/api/usage/{first['id']}", json={"status": "failed", "percent": 50})
    assert client.get("/api/spools").json()[1]["remaining_g"] == pytest.approx(993.83)
    # actually it was spool #1
    client.put(f"/api/usage/{first['id']}", json={"spool_id": s1})
    by = {s["id"]: s for s in client.get("/api/spools").json()}
    assert by[s2]["remaining_g"] == 1000 and by[s1]["remaining_g"] == pytest.approx(993.83)
    # didn't print at all
    client.put(f"/api/usage/{first['id']}", json={"status": "not_printed"})
    assert {s["id"]: s for s in client.get("/api/spools").json()}[s1]["remaining_g"] == 1000

    # weigh: 980 g on the scale with a 180 g spool = 800 g left
    w = client.post(f"/api/spools/{s1}/weigh", json={"gross_g": 980}).json()
    assert w["remaining_g"] == 800 and w["difference_g"] == 200 and w["percent"] == 80
    s3 = third["id"]
    # set it empty and it drops off the active list
    client.put(f"/api/spools/{s3}", json={"status": "empty"})
    assert s3 not in [s["id"] for s in client.get("/api/spools").json()]
    assert len(client.get(f"/api/profiles/{prof['id']}").json()["spools"]) == 3


def test_report_matches_filament_by_gcode_when_nothing_loaded(client):
    prof = _profile(client)
    sp = client.post("/api/spools", json={"profile_id": prof["id"]}).json()[0]
    client.post("/api/usage/report", json={"job": "cube", "usage": spools.parse_usage(GCODE)})
    left = {s["id"]: s for s in client.get("/api/spools").json()}[sp["id"]]["remaining_g"]
    assert left == pytest.approx(987.66)
    use = client.get("/api/usage").json()
    other = next(u for u in use if u["slot"] == 3)
    assert other["spool_id"] is None and other["filament"] == "Generic PETG"


def test_report_cli_when_app_is_closed(tmp_path, monkeypatch):
    import run
    from forge import app as app_mod
    monkeypatch.setattr(app_mod, "DATA_DIR", tmp_path)
    g = tmp_path / "x.gcode"
    g.write_text(GCODE)
    monkeypatch.setenv("SLIC3R_PP_OUTPUT_NAME", str(tmp_path / "Benchy_PLA.gcode"))
    assert run.report(str(g), port=1) == 0  # nothing listening on port 1
    saved = json.loads((tmp_path / "pending_usage.jsonl").read_text().splitlines()[0])
    assert saved["job"] == "Benchy_PLA" and saved["usage"]["total_g"] == 15.55
    assert g.read_text() == GCODE  # never touches the G-code


def test_weigh_without_empty_spool_weight(client):
    prof = _profile(client)
    new, used = client.post("/api/spools", json={"profile_id": prof["id"], "count": 2}).json()

    # a brand-new spool: the empty spool weight is worked out
    r = client.post(f"/api/spools/{new['id']}/weigh", json={"gross_g": 1185}).json()
    assert r["mode"] == "new" and r["tare_g"] == 185 and r["remaining_g"] == 1000
    # a new spool can't weigh less than its filament
    assert client.post(f"/api/spools/{used['id']}/weigh", json={"gross_g": 900}).status_code == 400

    # an opened spool with no empty weight: before, print, after
    client.put(f"/api/spools/{used['id']}", json={"remaining_g": 640})
    r = client.post(f"/api/spools/{used['id']}/weigh", json={"gross_g": 850}).json()
    assert r["mode"] == "baseline" and r["remaining_g"] == 640
    client.put("/api/printers/1/toolheads/1", json={"profile_id": prof["id"], "spool_id": used["id"]})
    client.post("/api/usage/report", json={"job": "vase", "usage": spools.parse_usage(GCODE)})  # 12.34 g on T1
    assert {s["id"]: s for s in client.get("/api/spools").json()}[used["id"]]["remaining_g"] == pytest.approx(627.66)
    r = client.post(f"/api/spools/{used['id']}/weigh", json={"gross_g": 836.5}).json()
    assert r["mode"] == "compare" and r["scale_used_g"] == 13.5 and r["counted_g"] == 12.3
    assert r["off_g"] == pytest.approx(1.2) and r["remaining_g"] == 626.5  # 640 at the first weigh, minus 13.5
    # with the empty weight known it's a plain subtraction again
    r = client.post(f"/api/spools/{used['id']}/weigh", json={"gross_g": 836.5, "tare_g": 200}).json()
    assert r["mode"] == "tare" and r["remaining_g"] == 636.5
